window.__rgjG=null; window.__rgjErr=null;
(async () => { try {
  const relay = (req) => new Promise(res => {
    const id = 'p' + Math.random().toString(36).slice(2);
    const t = setTimeout(() => { window.removeEventListener('message', h); res({ ok:false, status:0, text:'relay timeout' }); }, 9000);
    function h(ev) { const d = ev.data; if (!d || d.__rgjLan !== 1 || d.id !== id || !d.res) return;
      clearTimeout(t); window.removeEventListener('message', h); res(d.res); }
    window.addEventListener('message', h);
    window.postMessage({ __rgjLan: 1, id, req }, location.origin);
  });
  const base = 'http://192.168.1.169';
  const out = { steps: [] };
  const login = await relay({ method:'POST', url: base + '/api/login', headers:{'Content-Type':'application/json'},
                              body: JSON.stringify({ username:'ark', password:'ark' }) });
  const tok = String(login.text||'').replace(/^"|"$/g,'').trim();
  const H = { 'X-Auth': tok };
  const note = (label, r) => out.steps.push([label, r.status, String(r.text).slice(0,160)]);

  // 1. mkdir by trailing slash
  note('mkdir-trailing', await relay({ method:'POST', url: base + '/api/resources/rgjtest?override=false', headers: H, body: '' }));
  note('mkdir-plain',    await relay({ method:'POST', url: base + '/api/resources/rgjtest2', headers: H, body: '' }));
  note('mkdir-json',     await relay({ method:'POST', url: base + '/api/resources/rgjtest3', headers: H, body: JSON.stringify({action:'mkdir'}) }));
  // 2. inspect
  const ls = await relay({ method:'GET', url: base + '/api/resources/?override=true', headers: H });
  try { const j = JSON.parse(ls.text); out.items = j.items.filter(i=>/^rgj/.test(i.name)).map(i=>[i.name, i.isDir]); } catch(e) { out.items = String(ls.text).slice(0,80); }
  // 3. write + read raw
  note('write-json', await relay({ method:'POST', url: base + '/api/resources/rgjtest/rgj-device.json?override=true',
     headers: { ...H, 'Content-Type': 'application/octet-stream' }, body: JSON.stringify({ schema:1, device_id:'g350_hw01', probe:true }) }));
  note('read-raw', await relay({ method:'GET', url: base + '/api/raw/rgjtest/rgj-device.json', headers: H }));
  // 4. stray-file delete of the rgj artifact (my own, content {"action": "mkdir"})
  note('del-stray', await relay({ method:'DELETE', url: base + '/api/resources/rgj?override=true', headers: H }));
  note('mkdir-rgj', await relay({ method:'POST', url: base + '/api/resources/rgj?override=false', headers: H, body: '' }));
  window.__rgjG = JSON.stringify(out);
} catch(e) { window.__rgjErr = String(e && e.stack || e); } })();
